int open_msr(struct inode *inode, struct file *file) {
    int cpu;
    int err;

    /* Retrieve the CPU identifier from the file's path */
    cpu = smp_processor_id();

    /* Check if the CPU is valid and online */
    if (!cpu_online(cpu))
        return -ENXIO;

    /* Check if the CPU supports MSR operations */
    if (!boot_cpu_has(X86_FEATURE_MSR)) {
        err = -EIO;
        goto out;
    }

    return 0;

