int open_msr(struct inode *inode, struct file *file) {
    int cpu = -1;
    int ret = 0;

    if (!capable(CAP_SYS_RAWIO))
        return -EPERM;

    cpu = get_cpu_from_path(file->f_path.dentry->d_name.name);
    if (cpu < 0 || cpu >= nr_cpu_ids)
        return -ENXIO;

    if (!cpu_online(cpu))
        return -ENXIO;

    if (!cpu_has_msr(cpu))
        return -EIO;

    return ret;
}

